import{_ as l,a0 as o,w as d,s as r,I as i,x as a,a1 as e,A as p,ao as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"在 Linux 中使用 bd 命令快速返回到特定的父目錄 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 中使用 bd 命令快速返回到特定的父目錄 | LCTT (201904) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 中使用 bd 命令快速返回到特定的父目錄 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 中使用 bd 命令快速返回到特定的父目錄 | LCTT (201904) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201904/20190320 Quickly Go Back To A Specific Parent Directory Using bd Command In Linux","title":"在 Linux 中使用 bd 命令快速返回到特定的父目錄","tag":"201904","desc":""},"relativePath":"201904/20190320 Quickly Go Back To A Specific Parent Directory Using bd Command In Linux.md","filePath":"[post].md"}'),u={name:"201904/20190320 Quickly Go Back To A Specific Parent Directory Using bd Command In Linux.md"};function c(h,s,g,b,k,x){const n=o("Link");return d(),r("div",null,[s[32]||(s[32]=i("h1",{id:"在-linux-中使用-bd-命令快速返回到特定的父目錄",tabindex:"-1"},[a("在 Linux 中使用 bd 命令快速返回到特定的父目錄 "),i("a",{class:"header-anchor",href:"#在-linux-中使用-bd-命令快速返回到特定的父目錄","aria-label":"Permalink to “在 Linux 中使用 bd 命令快速返回到特定的父目錄”"},"​")],-1)),i("p",null,[s[1]||(s[1]=a("兩天前我們寫了一篇關於 ",-1)),s[2]||(s[2]=i("code",null,"autocd",-1)),s[3]||(s[3]=a(" 的文章，它是一個內置的 shell 變量，可以幫助我們在",-1)),e(n,{href:"https://www.2daygeek.com/navigate-switch-directory-without-using-cd-command-in-linux/"},{default:p(()=>[...s[0]||(s[0]=[a("沒有 cd 命令的情況下導航到目錄中",-1)])]),_:1}),s[4]||(s[4]=a("。",-1))]),s[33]||(s[33]=t('<p>如果你想回到上一級目錄，那麼你需要輸入 <code>cd ..</code>。</p><p>如果你想回到上兩級目錄，那麼你需要輸入 <code>cd ../..</code>。</p><p>這在 Linux 中是正常的，但如果你想從第九級目錄回到第三級目錄，那麼使用 <code>cd</code> 命令是很糟糕的。</p><p>有什麼解決方案呢？</p><p>是的，在 Linux 中有一個解決方案。我們可以使用 <code>bd</code> 命令來輕鬆應對這種情況。</p><h3 id="什麼是-bd-命令" tabindex="-1">什麼是 bd 命令？ <a class="header-anchor" href="#什麼是-bd-命令" aria-label="Permalink to “什麼是 bd 命令？”">​</a></h3><p><code>bd</code> 命令允許用户快速返回 Linux 中的父目錄，而不是反覆輸入 <code>cd ../../..</code>。</p><p>你可以列出給定目錄的內容，而不用提供完整路徑 ls <code>bd Directory_Name</code>。它支持以下其它命令，如 <code>ls</code>、<code>ln</code>、<code>echo</code>、<code>zip</code>、<code>tar</code> 等。</p><p>另外，它還允許我們執行 shell 文件而不用提供完整路徑 bd p<code>/shell_file.sh</code>。</p><h3 id="如何在-linux-中安裝-bd-命令" tabindex="-1">如何在 Linux 中安裝 bd 命令？ <a class="header-anchor" href="#如何在-linux-中安裝-bd-命令" aria-label="Permalink to “如何在 Linux 中安裝 bd 命令？”">​</a></h3><p>除了 Debian/Ubuntu 之外，<code>bd</code> 沒有官方發行包。因此，我們需要手動執行方法。</p>',11)),i("p",null,[s[7]||(s[7]=a("對於 Debian/Ubuntu 系統，使用 ",-1)),e(n,{href:"https://www.2daygeek.com/apt-get-apt-cache-command-examples-manage-packages-debian-ubuntu-systems/"},{default:p(()=>[...s[5]||(s[5]=[a("APT-GET 命令",-1)])]),_:1}),s[8]||(s[8]=a("或",-1)),e(n,{href:"https://www.2daygeek.com/apt-command-examples-manage-packages-debian-ubuntu-systems/"},{default:p(()=>[...s[6]||(s[6]=[a("APT 命令",-1)])]),_:1}),s[9]||(s[9]=a("來安裝 ",-1)),s[10]||(s[10]=i("code",null,"bd",-1)),s[11]||(s[11]=a("。",-1))]),s[34]||(s[34]=t('<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt install bd</span></span></code></pre></div>',1)),i("p",null,[s[13]||(s[13]=a("對於其它 Linux 發行版，使用 ",-1)),e(n,{href:"https://www.2daygeek.com/wget-command-line-download-utility-tool/"},{default:p(()=>[...s[12]||(s[12]=[a("wget 命令",-1)])]),_:1}),s[14]||(s[14]=a("下載 ",-1)),s[15]||(s[15]=i("code",null,"bd",-1)),s[16]||(s[16]=a(" 可執行二進制文件。",-1))]),s[35]||(s[35]=t(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo wget --no-check-certificate -O /usr/local/bin/bd https://raw.github.com/vigneshwaranr/bd/master/bd</span></span></code></pre></div><p>設置 <code>bd</code> 二進制文件的可執行權限。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo chmod +rx /usr/local/bin/bd</span></span></code></pre></div><p>在 <code>.bashrc</code> 文件中添加以下值。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo &#39;alias bd=&quot;. bd -si&quot;&#39; &gt;&gt; ~/.bashrc</span></span></code></pre></div><p>運行以下命令以使更改生效。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ source ~/.bashrc</span></span></code></pre></div><p>要啓用自動完成，執行以下兩個步驟。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo wget -O /etc/bash_completion.d/bd https://raw.github.com/vigneshwaranr/bd/master/bash_completion.d/bd  </span></span>
<span class="line"><span>$ sudo source /etc/bash_completion.d/bd</span></span></code></pre></div><p>我們已經在系統上成功安裝並配置了 <code>bd</code> 實用程序，現在是時候測試一下了。</p><p>我將使用下面的目錄路徑進行測試。</p><p>運行 <code>pwd</code> 命令或 <code>dirs</code> 命令，亦或是 <code>tree</code> 命令來了解你當前的路徑。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>daygeek@Ubuntu18:/usr/share/icons/Adwaita/256x256/apps$ pwd</span></span>
<span class="line"><span>或</span></span>
<span class="line"><span>daygeek@Ubuntu18:/usr/share/icons/Adwaita/256x256/apps$ dirs</span></span>
<span class="line"><span></span></span>
<span class="line"><span>/usr/share/icons/Adwaita/256x256/apps</span></span></code></pre></div><p>我現在在 <code>/usr/share/icons/Adwaita/256x256/apps</code> 目錄，如果我想快速跳轉到 <code>icons</code> 目錄，那麼只需輸入以下命令即可。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>daygeek@Ubuntu18:/usr/share/icons/Adwaita/256x256/apps$ bd icons</span></span>
<span class="line"><span>/usr/share/icons/</span></span>
<span class="line"><span>daygeek@Ubuntu18:/usr/share/icons$</span></span></code></pre></div><p>甚至，你不需要輸入完整的目錄名稱，也可以輸入幾個字母。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>daygeek@Ubuntu18:/usr/share/icons/Adwaita/256x256/apps$ bd i</span></span>
<span class="line"><span>/usr/share/icons/</span></span>
<span class="line"><span>daygeek@Ubuntu18:/usr/share/icons$</span></span></code></pre></div><p>注意：如果層次結構中有多個同名的目錄，<code>bd</code> 會將你帶到最近的目錄。（不考慮直接的父目錄）</p><p>如果要列出給定的目錄內容，使用以下格式。它會打印出 <code>/usr/share/icons/</code> 的內容。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -lh \`bd icons\`</span></span>
<span class="line"><span>或</span></span>
<span class="line"><span>daygeek@Ubuntu18:/usr/share/icons/Adwaita/256x256/apps$ ls -lh \`bd i\`</span></span>
<span class="line"><span>total 64K</span></span>
<span class="line"><span>drwxr-xr-x 12 root root 4.0K Jul 25  2018 Adwaita</span></span>
<span class="line"><span>lrwxrwxrwx  1 root root   51 Feb 25 14:32 communitheme -&gt; /snap/communitheme/current/share/icons/communitheme</span></span>
<span class="line"><span>drwxr-xr-x  2 root root 4.0K Jul 25  2018 default</span></span>
<span class="line"><span>drwxr-xr-x  3 root root 4.0K Jul 25  2018 DMZ-Black</span></span>
<span class="line"><span>drwxr-xr-x  3 root root 4.0K Jul 25  2018 DMZ-White</span></span>
<span class="line"><span>drwxr-xr-x  9 root root 4.0K Jul 25  2018 gnome</span></span>
<span class="line"><span>drwxr-xr-x  3 root root 4.0K Jul 25  2018 handhelds</span></span>
<span class="line"><span>drwxr-xr-x 20 root root 4.0K Mar  9 14:52 hicolor</span></span>
<span class="line"><span>drwxr-xr-x  9 root root 4.0K Jul 25  2018 HighContrast</span></span>
<span class="line"><span>drwxr-xr-x 12 root root 4.0K Jul 25  2018 Humanity</span></span>
<span class="line"><span>drwxr-xr-x  7 root root 4.0K Jul 25  2018 Humanity-Dark</span></span>
<span class="line"><span>drwxr-xr-x  4 root root 4.0K Jul 25  2018 locolor</span></span>
<span class="line"><span>drwxr-xr-x  3 root root 4.0K Feb 25 15:46 LoginIcons</span></span>
<span class="line"><span>drwxr-xr-x  3 root root 4.0K Jul 25  2018 redglass</span></span>
<span class="line"><span>drwxr-xr-x 10 root root 4.0K Feb 25 15:46 ubuntu-mono-dark</span></span>
<span class="line"><span>drwxr-xr-x 10 root root 4.0K Feb 25 15:46 ubuntu-mono-light</span></span>
<span class="line"><span>drwxr-xr-x  3 root root 4.0K Jul 25  2018 whiteglass</span></span></code></pre></div><p>如果要在父目錄中的某個位置執行文件，使用以下格式。它將運行 shell 文件 <code>/usr/share/icons/users-list.sh</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ \`bd i\`/users-list.sh</span></span>
<span class="line"><span>或</span></span>
<span class="line"><span>daygeek@Ubuntu18:/usr/share/icons/Adwaita/256x256/apps$ \`bd icon\`/users-list.sh</span></span>
<span class="line"><span>daygeek</span></span>
<span class="line"><span>thanu</span></span>
<span class="line"><span>renu</span></span>
<span class="line"><span>2gadmin</span></span>
<span class="line"><span>testuser</span></span>
<span class="line"><span>demouser</span></span>
<span class="line"><span>sudha</span></span>
<span class="line"><span>suresh</span></span>
<span class="line"><span>user1</span></span>
<span class="line"><span>user2</span></span>
<span class="line"><span>user3</span></span></code></pre></div><p>如果你位於 <code>/usr/share/icons/Adwaita/256x256/apps</code> 中，想要導航到不同的父目錄，使用以下格式。以下命令將導航到 <code>/usr/share/icons/gnome</code> 目錄。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cd \`bd i\`/gnome</span></span>
<span class="line"><span>或</span></span>
<span class="line"><span>daygeek@Ubuntu18:/usr/share/icons/Adwaita/256x256/apps$ cd \`bd icon\`/gnome</span></span>
<span class="line"><span>daygeek@Ubuntu18:/usr/share/icons/gnome$</span></span></code></pre></div><p>如果你位於 <code>/usr/share/icons/Adwaita/256x256/apps</code> ，你想在 <code>/usr/share/icons/</code> 下創建一個新目錄，使用以下格式。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ daygeek@Ubuntu18:/usr/share/icons/Adwaita/256x256/apps$ sudo mkdir \`bd icons\`/2g</span></span>
<span class="line"><span></span></span>
<span class="line"><span>daygeek@Ubuntu18:/usr/share/icons/Adwaita/256x256/apps$ ls -ld \`bd icon\`/2g</span></span>
<span class="line"><span>drwxr-xr-x 2 root root 4096 Mar 16 05:44 /usr/share/icons//2g</span></span></code></pre></div><p>本教程允許你快速返回到特定的父目錄，但沒有快速前進的選項。</p><p>我們有另一個解決方案，很快就會提出，請保持關注。</p><hr>`,29)),i("p",null,[s[18]||(s[18]=a("via: ",-1)),e(n,{href:"https://www.2daygeek.com/bd-quickly-go-back-to-a-specific-parent-directory-in-linux/"},{default:p(()=>[...s[17]||(s[17]=[a("https://www.2daygeek.com/bd-quickly-go-back-to-a-specific-parent-directory-in-linux/",-1)])]),_:1})]),i("p",null,[s[23]||(s[23]=a("作者：",-1)),e(n,{href:"https://www.2daygeek.com/author/magesh/"},{default:p(()=>[...s[19]||(s[19]=[a("Magesh Maruthamuthu",-1)])]),_:1}),s[24]||(s[24]=a(" 選題：",-1)),e(n,{href:"https://github.com/lujun9972"},{default:p(()=>[...s[20]||(s[20]=[a("lujun9972",-1)])]),_:1}),s[25]||(s[25]=a(" 譯者：",-1)),e(n,{href:"https://github.com/MjSeven"},{default:p(()=>[...s[21]||(s[21]=[a("MjSeven",-1)])]),_:1}),s[26]||(s[26]=a(" 校對：",-1)),e(n,{href:"https://github.com/wxy"},{default:p(()=>[...s[22]||(s[22]=[a("wxy",-1)])]),_:1})]),i("p",null,[s[29]||(s[29]=a("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...s[27]||(s[27]=[a("LCTT",-1)])]),_:1}),s[30]||(s[30]=a(" 原創編譯，",-1)),e(n,{href:"https://linux.cn/"},{default:p(()=>[...s[28]||(s[28]=[a("Linux中國",-1)])]),_:1}),s[31]||(s[31]=a(" 榮譽推出",-1))])])}const w=l(u,[["render",c]]);export{y as __pageData,w as default};
